const roleName=p=>roleDef(roleKeyOf(p||me())).n;
const isOwner=()=>typeof IS_TEST!=='undefined'&&!IS_TEST
  ?!!SERVER_AUTH&&SERVER_AUTH.role===ROLE_OWNER:roleKeyOf(me())===ROLE_OWNER;
const isClubSupervisor=()=>typeof IS_TEST!=='undefined'&&!IS_TEST
  ?!!SERVER_AUTH&&SERVER_AUTH.role===ROLE_CLUB:roleKeyOf(me())===ROLE_CLUB;
const isManager=()=>typeof IS_TEST!=='undefined'&&!IS_TEST
  ?!!SERVER_AUTH&&[ROLE_MANAGER,ROLE_CLUB].includes(SERVER_AUTH.role)
  :roleKeyOf(me())===ROLE_MANAGER||isClubSupervisor();
const canManageClub=()=>isOwner()||isClubSupervisor();
/* نام قدیمیِ داخلی برای دسترسی مدیریتی عمومی؛ دیگر نقش جداگانه‌ای نیست. */
const isLead=()=>isManager();
const canSimRole=()=>{if(typeof IS_TEST!=='undefined'&&!IS_TEST)return false;
  const a=readAdminSession(); return validAdminSession(a)?roleKeyOf(personOf(a.personKey))===ROLE_OWNER:IS_TEST;};
const leadK=f=>S.leads[f]||fieldOf(f).lead;
const leadOf=f=>personOf(leadK(f));
const teamOf=f=>allP().filter(p=>p.f===f&&p.k!==leadK(f));
const fieldSecs=()=>ALLSECS.map(s=>s.k);
const canSec=k=>{
  if(IS_TEST) return fieldSecs().indexOf(k)>-1||k==='newev';
  if(!SERVER_AUTH||!ROLE_KEYS.includes(SERVER_AUTH.role)) return false;
  if(k==='dash') return true;
  if(k==='newev') return canSec('events');
  if(k==='events') return canPerm('ev_create')||canPerm('pr_media');
  if(k==='users') return canPerm('us_view');
  if(k==='forms') return canPerm('fm_create')||canPerm('fm_responses');
  if(k==='settings') return isOwner();
  return false;
};
const fieldOfSec=k=>FIELDS.find(f=>f.k!=='owner'&&(f.sections||[]).indexOf(k)>-1);
/* کارتابل عمومی برای مدیران؛ حوزه در داشبورد فقط دسته‌بندی کارهاست. */
const qDone=id=>(S.qdone||[]).indexOf(id)>-1;
const qWho=it=>(S.qgive||{})[it.id]||it.who;
const qAll=()=>QUEUE.concat(S.qextra||[]);
const myQueue=()=>qAll().filter(it=>isOwner()||isManager()?true:qWho(it)===me().k);
const qOpen=()=>myQueue().filter(it=>!qDone(it.id));
function canPerm(p){
  if(!IS_TEST&&SERVER_AUTH) return Array.isArray(SERVER_AUTH.permissions)&&SERVER_AUTH.permissions.includes(p);
  const row=PROWS.find(r=>r[0]===p); if(!row) return false;
  if(isOwner()) return true;
  if(row[2]==='owner'||p==='cl_dues'||p==='sys_points') return false;
  if(row[2]==='club') return isClubSupervisor();
  return isManager();
}

