const NTF_SAMP={'{نام}':'علی محمدی','{رویداد}':'کارگاه روایت اول‌شخص','{ساعت}':'۱۷:۰۰','{جا}':'لانه',
  '{کد}':'NR2094','{عدد}':'۳۰','{شرط}':'پنج حضور','{امتیاز}':'۲۴۰','{مبلغ}':'۹۸۰٬۰۰۰',
  '{تاریخ}':'دوشنبه ۱۲ مهر ۱۴۰۵','{دوست}':'سارا','{دلیل}':'تکمیل ظرفیت','{نشان}':'پرحضور'};
const ntfFrom=()=>S.ntfFrom||'نورا';
const ntfFill=s=>String(s||'').replace(/\{[^\}]+\}/g,m=>NTF_SAMP[m]||m);
const ntfT=nt=>{const o=(S.ntfT||{})[nt.k]||{}; return {t:o.t!=null?o.t:nt.t, b:o.b!=null?o.b:nt.b, s:o.s!=null?o.s:nt.s}};
const ntfCh=nt=>{const x=Object.assign({bale:1,acc:1,eitaa:0},nt.ch||{},((S.ntfCh||{})[nt.k])||{});
  return {bale:x.bale?1:0,eitaa:x.eitaa?1:0,acc:x.acc?1:0}};
const ntfOn=nt=>(S.ntfOff||[]).indexOf(nt.k)<0;
const ntfClock=k=>((S.ntfClock||{})[k])||(k==='bday'?'۹:۰۰':'۲۰:۰۰');
const ntfStamp=()=>{const j=jNow(); return {d:fa(j.jy)+'/'+fa(j.jm)+'/'+fa(j.jd), t:fa(j.h)+':'+fa(jPad(j.mi))}};
const ntfWhen=nt=>'پیشنهاد: '+(nt.k==='remind'?('شب قبل، ساعت '+ntfClock('remind')):nt.k==='bday'?('زمان مناسبت، ساعت '+ntfClock('bday')):nt.when)+' · زمان‌بندی و ارسال غیرفعال';
function ntfNote(k,recipients,options){ /* همهٔ اعلان‌های خروجی برای بازبینی مالک می‌روند؛ در این نمونه ارسال واقعی نداریم */
  const nt=NTF.find(x=>x.k===k); if(!nt) return null;
  const N=ntfT(nt), opt=options||{}, recs=(Array.isArray(recipients)?recipients:recipients?[recipients]:[]).map(x=>({
    userId:x.userId||x.id||x.u||'',name:x.name||x.n||'',mobile:x.mobile||x.ph||'',eventId:x.eventId||x.ev||'',
    eventTitle:x.eventTitle||x.event||''}));
  const row=ownerQueueAdd({type:'notification',status:'pending',source:opt.source||'notification-trigger',key:k,
    title:N.t,notification:{title:N.t,body:N.b,subtitle:N.s||''},recipients:recs,allRecipients:!!opt.allRecipients,
    testOnly:!!opt.testOnly,channels:ntfCh(nt),requestedBy:me().n||'همکار',requestedById:me().k,
    requestedRole:me().f,requestedAt:Date.now()});
  if(row){uLogAdd('درخواست اعلان «'+N.t+'» برای بازبینی مالک ثبت شد؛ هنوز ارسال نشده');save()}
  return row||null;
}
function requestOwnerNotice(input){
  const x=Object.assign({},input||{}), title=x.title||'اطلاع‌رسانی';
  if(!x.notification) x.notification={title:title,body:String(x.body||'')};
  x.type='notification'; x.status='pending';
  x.requestedBy=x.requestedBy||me().n||'همکار'; x.requestedById=x.requestedById||me().k;
  x.requestedRole=x.requestedRole||me().f; x.requestedAt=x.requestedAt||Date.now();
  return ownerQueueAdd(x);
}
function queueAllMembersNotice(title,body,source){
  return requestOwnerNotice({source:source||'club-announcement',title:title||'اعلان باشگاه',
    notification:{title:title||'اعلان باشگاه',body:body||''},recipients:[],allRecipients:true,channels:{acc:1,bale:1,eitaa:1}});
}
function ntfFire(k){ /* نمونه فقط برای بازبینی مالک است؛ گیرنده و ارسال واقعی ندارد */
  const nt=NTF.find(x=>x.k===k); if(!nt) return;
  const row=ntfNote(k,[],{source:'notification-sample',testOnly:true});
  toast(row?'نمونهٔ اعلان در صف بازبینی مالک؛ هیچ پیامی ارسال نشد':'صف تأیید مالک در دسترس نیست');
  renderBody(); }

/* ── رویدادها ──────────────────────────────────────────────────────────── */
const EV=A.events||{}, EVROWS=EV.rows||[];
/* فرم‌های ساختهٔ ویزارد، به رویدادش چسبیده، می‌مانند تا در بخش فرم‌ها هم دیده شوند */
function linkForms(evId, w0){
  const w=w0||S.wiz, fp=Object.assign({},w.fp||{}), u=(window.NORA_UI&&NORA_UI)||null, out=[];
  ['reg','survey','exam','other'].forEach(need=>{
    const id=fp[need]; if(!id) return;
    const f=formOf(id); if(!f) return;
    /* فرم‌ساز و رویداد یکی می‌مانند: ظرفیت و پنجرهٔ ثبت‌نام به فرم می‌رود */
    try{
      if(!f.demo&&u&&u.formPatch) u.formPatch(id,{ev:evId, need:need,
        cap:+w.cap||f.cap||0, start:w.regFrom||w.date||f.start||'', ends:w.regTo||w.end||f.ends||'',
        sync:{cap:1,dates:1,money:1}});
    }catch(e){}
    out.push({id:String(id), need:need, n:formName(f), q:formQs(f), money:formSum(f), ev:evId,
      link:'form.html?ev='+evId+'&kind='+need});
  });
  return out;
}
/* ویرایش آزاد است و وضعیت را عوض نمی‌کند: هر رویداد می‌تواند روکش ویرایش داشته باشد */
const evAll=()=>{const ov=S.evEdit||{};
  return (S.added||[]).concat(EVROWS).map(e=>ov[e.id]?Object.assign({},e,ov[e.id]):e);};
const evOf=id=>evAll().find(e=>e.id===id)||null;
const eventPartnerRows=()=>{try{
  if(typeof ppPartnerServerMode==='function'&&ppPartnerServerMode()&&!PP_SRV.loaded&&!PP_SRV.requested) ppPartnerServerLoad();
  return typeof ppPartnerMerged==='function'?ppPartnerMerged():((window.NORA||{}).PARTNERS||[])}catch(e){return []}};
const eventPartnerOf=id=>{if(!id)return null; try{return (typeof ppPartnerAll==='function'?ppPartnerAll():((window.NORA||{}).PARTNERS||[]))
  .find(row=>String(row.id)===String(id))||null}catch(e){return null}};
const eventPartnerName=event=>{
  const row=event&&typeof event==='object'?event:null;
  const partner=eventPartnerOf(row?row.partnerId:event);
  return (partner&&partner.n)||(row&&row.partnerName)||'';
};
/* عدد و یکا: رقم درشت می‌ماند و واژهٔ یکا ریز و کم‌رنگ کنارش می‌نشیند تا هیچ
   عددی درشت و بی‌توضیح نماند و در تنگی جا هم شکسته شود، نه سرریز */
const bits=v=>{const t=String(v==null?'':v).trim(), i=t.search(/\s/);
  return i<0?`<b>${esc(t)}</b>`:`<b>${esc(t.slice(0,i))} <small class="ku">${esc(t.slice(i+1))}</small></b>`;};
const evFilter=f=>f==='live'?e=>evState(e)==='live' : f==='soon'?e=>evState(e)==='soon'
  : f==='past'?e=>evState(e)==='past' : ()=>true;
/* وضعیت هر ردیف: برگزاری تمام شده؟ خودش رفته در برگزار شده */
