/* ── کارت رویداد، زنده از دلِ فرم‌ساز: ثبت‌نام‌ها، پرونده‌ها، اطلاع‌رسانی و نظرسنجی ──
   هیچ صفحهٔ جدا ندارد؛ هر چه هست همین‌جا در ورقهٔ خود رویداد است. */
const NUI=()=>(window.NORA_UI)||{};
/* پاسخ‌های محلیِ فرم رویداد؛ دادهٔ مرورگر است و ثبت‌نام عملیاتی محسوب نمی‌شود. */
const uiRegs=e=>{try{const u=NUI(); const all=u.regsOf?u.regsOf(e.id):[];
  const skip={}; (u.formsFor?u.formsFor(e.id):[]).forEach(f=>{if((f.need||'reg')!=='reg') skip[String(f.id)]=1});
  return all.filter(r=>!skip[String(r.form)])}catch(err){return []}}
const uiForms=e=>{try{const u=NUI(); return u.formsFor?u.formsFor(e.id):[]}catch(err){return []}}
const regName=r=>{const a=(r.ans||[]).find(x=>/^نام/.test(x.l)); return a&&a.v?String(a.v):'بی‌نام'};
const regMob=r=>{const a=(r.ans||[]).find(x=>/موبایل|تلفن/.test(x.l)); return a?String(a.v||''):''};
const personOfReg=r=>{try{const u=NUI();
  if(u.personById&&r.pid){const p=u.personById(r.pid); if(p) return p}
  const mob=regMob(r).replace(/[^\d]/g,'').slice(-10);
  if(mob&&u.peopleAll) return u.peopleAll().find(p=>p.mobile===mob)||null;
  return null}catch(err){return null}};
function certRecipients(){
  const out=[], eventIds=(S.cert&&S.cert.evs||[]).filter(id=>EVROWS.some(e=>e.id===id));
  const genericEvent=eventIds.length===1?(EVROWS.find(e=>e.id===eventIds[0])||null):null;
  const add=(x,e,source)=>{
    x=x||{}; const name=String(x.name||x.n||'').trim(); if(!name||name==='بی‌نام') return;
    const mobile=String(x.mobile||x.ph||''), personId=String(x.personId||x.userId||x.id||'');
    const eid=String((e&&e.id)||x.eventId||''), key=eid+'|'+(personId||mobile.replace(/\D/g,'').slice(-10)||norm(name));
    if(out.some(r=>r._key===key)) return;
    out.push({_key:key,userId:personId,personId:personId,name,mobile:mobile,nationalId:x.nationalId||x.nid||'',
      code:x.code||'',eventId:eid,eventTitle:(e&&e.n)||x.eventTitle||'',source:source||'manual'});
  };
  eventIds.forEach(id=>{const e=EVROWS.find(x=>x.id===id); if(!e)return;
    uiRegs(e).forEach(r=>{const p=personOfReg(r)||{}, rn=regName(r); add({userId:p.id||r.pid||'',
      name:rn==='بی‌نام'?(p.fullName||p.name||''):rn,mobile:regMob(r)||p.mobile||'',
      nationalId:p.nid||'',code:r.code||p.code||''},e,'event')});
  });
  (S.cert&&S.cert.tags||[]).forEach(t=>memList().filter(m=>(m.tags||[]).indexOf(t)>-1)
    .forEach(m=>add({id:m.id,name:m.n,ph:m.ph,nid:m.nid,code:m.code},genericEvent,'tag')));
  (S.cert&&S.cert.xlsRows||[]).forEach(x=>add(x,genericEvent,'spreadsheet'));
  (S.cert&&S.cert.picked||[]).forEach(id=>{const m=memOf(id); if(m)add({id:m.id,name:m.n,ph:m.ph,nid:m.nid,code:m.code},genericEvent,'manual')});
  return out.map(({_key,...r})=>r);
}
const certQueueItems=()=>ownerQueue().filter(x=>x&&['cert-batch','cert-request'].includes(x.type));
const CERT_OUTPUT_DEFAULTS={name:true,title:true,kind:true,date:true,hours:true,serial:true,qr:false};
const TICKET_OUTPUT_DEFAULTS={event:true,name:true,date:true,time:true,place:true,seat:true,serial:true,qr:true};
const certInclude=()=>Object.assign({},CERT_OUTPUT_DEFAULTS,(S.cert&&S.cert.include)||{});
const ticketInclude=()=>Object.assign({},TICKET_OUTPUT_DEFAULTS,(S.ticket&&S.ticket.include)||{});
const certSerialFor=seed=>'NL-'+((UI.shortCode?UI.shortCode(String(seed||Date.now())):String(Date.now()).slice(-7)));
const certFieldsFor=(job,r,serial,approver)=>({name:r&&r.name||'شرکت‌کننده',
  title:r&&r.eventTitle||job&&job.eventTitle||job&&job.title||'برنامهٔ آموزشی',
  kind:job&&job.kind||'گواهینامهٔ پایان دوره',date:job&&job.issueDate||ntfStamp().d,
  hours:r&&r.hours||job&&job.hours||'',code:r&&r.code||'',serial:serial||r&&r.serial||'',
  approver:approver||'مالک سامانه',include:Object.assign({},CERT_OUTPUT_DEFAULTS,job&&job.include||{}),
  custom:Object.keys((job&&job.customValues)||{}).map(key=>({key,value:job.customValues[key]})),
  format:(job&&job.outputFormat)||job&&job.format||'pdf'});
function ownerApproveCertificate(id){
  if(!isOwner()){toast('صدور نمونه و اطلاع‌رسانی فقط پس از تأیید صریح مالک ممکن است');return}
  const item=ownerQueue().find(x=>x&&String(x.id)===String(id));
  if(!item||item.status!=='pending'||!['cert-batch','cert-request'].includes(item.type)){toast('درخواست صدور در صف بررسی نیست');return}
  const recs=Array.isArray(item.recipients)?item.recipients:(item.recipient?[item.recipient]:[]);
  if(!recs.length){toast('برای صدور نمونه، دست‌کم یک گیرندهٔ نام‌دار لازم است');return}
  const now=Date.now(), approvedBy=me().n||'مالک سامانه', approvedById=String(me().k||'');
  if(!approvedById){toast('شناسهٔ نقش مالک در پیش‌نمایش در دسترس نیست؛ چیزی صادر نشد');return}
  const notification=item.notification||{title:'پیش‌نمایش گواهی پس از تأیید مالک',
    body:'{نام} عزیز، گواهی نمونهٔ «{رویداد}» با سریال {کد} فقط در حساب محلی نمایش داده شد؛ پیامی ارسال نشده است.'};
  /* نخست، تأیید صریح مالک را در صف محلی ثبت می‌کنیم؛ موتور صدور بدون این شناسه رد می‌شود. */
  const approved=ownerQueuePatch(item.id,{status:'approved',approvedBy,approvedById,approvedAt:now,
    notification:notification,notificationStatus:'pending'});
  if(!approved||approved.status!=='approved'||!approved.approvedById){toast('تأیید مالک در صف محلی ثبت نشد؛ گواهی صادر نشد');return}
  const final=[];
  recs.forEach((r,i)=>{
    const serial=r.serial||certSerialFor(item.id+':'+(r.userId||r.mobile||r.name||i));
    const f=certFieldsFor(item,r,serial,approvedBy), row=Object.assign({},r,f,{serial,state:'issued',
      outputFormat:item.outputFormat||item.format||'pdf',deliveryChannel:'bale',deliveryEnabled:false,sent:false,
      approvedBy:approvedBy,approvedById:approvedById,approvedAt:now,ownerApprovalId:item.id,
      source:item.source||'admin',localOnly:true});
    const saved=issuedCertAdd(row,item.id);
    if(saved) final.push(saved);
  });
  if(final.length!==recs.length){
    ownerQueuePatch(item.id,{recipients:final,issuedCount:final.length,notificationStatus:'pending'});
    save(); renderBody(); toast('تأیید محلی ثبت شد، اما همهٔ رکوردهای نمونه ذخیره نشدند؛ اعلانی نمایش داده نشد'); return;
  }
  ownerQueuePatch(item.id,{recipients:final,notification:notification,
    notificationStatus:'approved',issuedCount:final.length});
  S.certQueue=(S.certQueue||[]).map(b=>b.ownerQueueId===item.id?Object.assign({},b,{st:'approved',got:final.length,
    plan:'تأیید صریح مالک · '+approvedBy,ownerApproved:1}):b);
  S.jobs=(S.jobs||[]).map(j=>j.approvalId===item.id?Object.assign({},j,{st:'approved',at:'تأیید صریح مالک'}):j);
  uLogAdd(fa(final.length)+' رکورد گواهی نمونه در رجیستری محلی ثبت شد؛ اعلان محلی فقط پس از تأیید مالک نمایش داده شد و چیزی ارسال نشد');
  save(); renderBody();
  toast('مالک صریحاً تأیید کرد؛ گواهی فقط در حساب محلی نمایش داده شد و هیچ پیام بیرونی ارسال نشد');
}
function ownerRejectCertificate(id){
  if(!isOwner()){toast('رد درخواست صدور هم فقط با مالک است');return}
  const item=ownerQueue().find(x=>x&&String(x.id)===String(id));
  if(!item||item.status!=='pending'){toast('درخواست در صف بررسی نیست');return}
  ownerQueuePatch(item.id,{status:'rejected',rejectedBy:me().n||'مالک سامانه',rejectedAt:Date.now()});
  S.certQueue=(S.certQueue||[]).map(b=>b.ownerQueueId===item.id?Object.assign({},b,{st:'rejected'}):b);
  S.jobs=(S.jobs||[]).map(j=>j.approvalId===item.id?Object.assign({},j,{st:'rejected',at:'رد مالک'}):j);
  save(); renderBody(); toast('درخواست با تصمیم مالک رد شد؛ صدور و اطلاع‌رسانی انجام نشد');
}
function ownerApproveNotice(id){
  if(!isOwner()){toast('تأیید اطلاع‌رسانی فقط با مالک است');return}
  const item=ownerQueue().find(x=>x&&String(x.id)===String(id));
  if(!item||item.status!=='pending'||item.type!=='notification'){toast('اطلاع‌رسانی در صف مالک نیست');return}
  const approved=ownerQueuePatch(item.id,{status:'approved',approvedBy:me().n||'مالک سامانه',
    approvedById:me().k||'',approvedAt:Date.now(),notificationStatus:'approved'});
  if(approved&&item.brRecord&&NUI().brSave) NUI().brSave(item.brRecord,approved.id);
  S.ntfLog=[{at:ntfStamp().d+' · '+ntfStamp().t,who:me().n||'مالک',t:item.title||'اطلاع‌رسانی',k:item.key||'_approved',status:'approved'}].concat(S.ntfLog||[]).slice(0,40);
  uLogAdd(item.testOnly?'نمونهٔ اعلان «'+(item.title||'')+'» بازبینی محلی شد؛ ارسال نشد':'اطلاع‌رسانی «'+(item.title||'')+'» با تأیید صریح مالک فقط به‌صورت اعلان محلی و ارسال‌نشده ثبت شد');
  save(); renderBody(); toast(item.testOnly?'نمونه بازبینی محلی شد؛ هیچ پیامی ارسال نشد':'تأیید مالک فقط یک اعلان محلی ساخت؛ هیچ پیام یا اعلانی بیرون از مرورگر ارسال نشد');
}
function ownerRejectNotice(id){
  if(!isOwner()){toast('رد اطلاع‌رسانی فقط با مالک است');return}
  const item=ownerQueue().find(x=>x&&String(x.id)===String(id));
  if(!item||item.status!=='pending'||item.type!=='notification'){toast('اطلاع‌رسانی در صف مالک نیست');return}
  ownerQueuePatch(item.id,{status:'rejected',rejectedBy:me().n||'مالک سامانه',rejectedAt:Date.now()});
  save(); renderBody(); toast('اطلاع‌رسانی رد شد و برای کاربر فرستاده نشد');
}
