  if(!onPast&&past&&d) warns.push({t:'علامت «برگزارشده» دارد ولی تاریخش نگذشته است.',to:'sched'});
  if(endBefore) warns.push({t:'ساعت پایان پیش از شروع است؛ سرور آن را نمی‌پذیرد.',to:'main'});
